import java.io.DataInputStream;

public class Main {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int answer = new Solver().calculate(n);
        System.out.print(answer);
        dis.close();
    }

    static class Solver {
        int calculate(int n) {
            int[][][] dp = new int[2 * n + 1][2 * n + 1][2];
            dp[0][0][0] = 1;
            for (int depth = 1; depth <= 2 * n; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    if (opened - 1 >= 0) {
                        dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
                    }
                    if (opened + 1 <= n) {
                        dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
                    }
                    dp[depth][opened][0]++;
                    dp[depth][opened][0] %= 1_000_000_007;
                    dp[depth][opened][1] %= 1_000_000_007;
                }
            }
            return dp[2 * n][0][1];
        }

        static int readInt(DataInputStream dis) throws Exception {
            int ret = 0;
            int c = dis.read();
            while (isSpaceChar(c)) {
                c = dis.read();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = dis.read();
            }
            do {
                ret = ret * 10 + c - '0';
                c = dis.read();
            } while (!isSpaceChar(c));
            return negative ? -ret : ret;
        }

        static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
